import{c as n,Q as e,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const t="/assets/ChannelSplit%E5%8A%9F%E8%83%BD%E7%A4%BA%E6%84%8F%E5%9B%BE.DtX6oIv_.png",u=JSON.parse('{"title":"矩阵乘输出的Channel拆分","description":"","frontmatter":{},"headers":[{"level":1,"title":"矩阵乘输出的Channel拆分","slug":"矩阵乘输出的channel拆分"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵乘输出的Channel拆分.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵乘输出的Channel拆分.md"}'),p={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵乘输出的Channel拆分.md"};function i(r,a,o,c,h,m){return e(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="矩阵乘输出的channel拆分" tabindex="-1">矩阵乘输出的Channel拆分 <a class="header-anchor" href="#矩阵乘输出的channel拆分" aria-label="Permalink to &quot;矩阵乘输出的Channel拆分&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>矩阵乘输出的Channel拆分，又称ChannelSplit。指当Matmul计算结果C矩阵的格式为<a href="./../基础知识.html#zh-cn_topic_0000001622194138_section1453415011">NZ</a>时，C矩阵采用分形存储，关于NZ格式的详细内容请参考<a href="./../基础知识.html#zh-cn_topic_0000001622194138_section1453415011">数据格式</a>。当C矩阵的物理排布格式为NZ、数据类型为float时，默认情况下，每个分形内部包含16*16个元素，即分形的大小为16*16。ChannelSplit的功能为将此场景下C矩阵的每个16*16的分形切分为16*8的分形，使得C矩阵按照16*8的分形进行存储。</p><p>由于1个float类型数据的大小为4字节，16*8的分形在内轴满足32字节对齐，内轴上的数据量与一条NPU矢量计算指令处理的数据单元一致，这便于后续的其它计算。ChannelSplit功能默认不启用，用户需通过设置<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MatmulConfig</a>中的isEnableChannelSplit参数为true来开启此功能。</p><p><strong>图 1</strong> ChannelSplit功能示意图<br><img src="'+t+`" alt="" title="ChannelSplit功能示意图"></p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>对于NZ格式、float类型的C矩阵，需要按16*8的分形存储时，使用该功能。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>开启ChannelSplit功能需满足：</p><ul><li>C矩阵的数据排布格式为CubeFormat::NZ。</li><li>C矩阵的数据类型为float。</li><li>C矩阵的内存逻辑位置为Global Memory。</li><li>矩阵乘结果CO1数据类型为float。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_channelsplit_output" target="_blank" rel="noreferrer">matmul_channelsplit算子样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 指定获取和修改的MatmulConfig模板</span></span>
<span class="line"><span>constexpr static MatmulConfigMode configMode = MatmulConfigMode::CONFIG_NORM;</span></span>
<span class="line"><span>// 修改模板参数isEnableChannelSplit=true，开启该MatmulConfig模板的ChannelSplit功能</span></span>
<span class="line"><span>constexpr static MatmulFuncParams funcParamsChannelSplit{</span></span>
<span class="line"><span>    false, false, false, false, 0, IterateOrder::ORDER_M, ScheduleType::INNER_PRODUCT, true, false, false, false, true/*isEnableChannelSplit*/</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>constexpr static MatmulConfig MM_CFG = GetMMConfig&lt;configMode&gt;(funcParamsChannelSplit);</span></span>
<span class="line"><span>Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG&gt; mm;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 常规Matmul计算，最后输出分形为16*8</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>mm.SetBias(gm_bias);</span></span>
<span class="line"><span>mm.IterateAll(gm_c);</span></span></code></pre></div>`,13)])])}const d=n(p,[["render",i]]);export{u as __pageData,d as default};
